def peak_inventory_day(inventory: list[int]) -> int:
    # Pass 1: find the maximum value
    max_val = inventory[0]
    for val in inventory:
        if val > max_val:
            max_val = val

    # Pass 2: find the first index where this maximum occurs
    for i, val in enumerate(inventory):
        if val == max_val:
            return i

    return 0  # Should never reach here given n_min=1

