def peak_inventory_day(inventory: list[int]) -> int:
    max_val = inventory[0]
    max_idx = 0

    for i in range(1, len(inventory)):
        # Only update on strictly greater to preserve earliest index
        if inventory[i] > max_val:
            max_val = inventory[i]
