def longest_basket_window(stalls: list[int], k: int) -> int:
    n = len(stalls)
    max_len = 0

    for i in range(n):
        freq = {}
        for j in range(i, n):
            # Add stalls[j] to the current window
            freq[stalls[j]] = freq.get(stalls[j], 0) + 1
            # If distinct count exceeds k, stop extending
            if len(freq) > k:
                break
            max_len = max(max_len, j - i + 1)

    return max_len

def find_anagram_positions(text: str, pattern: str) -> list[int]:
    n, m = len(text), len(pattern)
    if m > n:
        return []

    sorted_pattern = sorted(pattern)
    result = []

    for i in range(n - m + 1):
        # Extract window and sort it
        if sorted(text[i:i + m]) == sorted_pattern:
            result.append(i)

    return result

