def find_anagram_positions(text: str, pattern: str) -> list[int]:
    n, m = len(text), len(pattern)
    if m > n:
        return []

    # Build frequency arrays for pattern and first window
    pat_freq = [0] * 26
    win_freq = [0] * 26

    for ch in pattern:
        pat_freq[ord(ch) - ord('a')] += 1
    for ch in text[:m]:
        win_freq[ord(ch) - ord('a')] += 1

    result = []
    if win_freq == pat_freq:
        result.append(0)

    # Slide window from index 1 to n-m
    for i in range(1, n - m + 1):
        # Add incoming character (right end of new window)
        win_freq[ord(text[i + m - 1]) - ord('a')] += 1
        # Remove outgoing character (left end of old window)
        win_freq[ord(text[i - 1]) - ord('a')] -= 1

        if win_freq == pat_freq:
            result.append(i)

    return result

