def max_circular_pressure(pressure: list[int]) -> int:
    n = len(pressure)
    max_sum = float('-inf')

    for start in range(n):
        current_sum = 0
        for length in range(1, n + 1):
            idx = (start + length - 1) % n
            current_sum += pressure[idx]
            max_sum = max(max_sum, current_sum)

    return max_sum
